/* Role-based learning guides — Programmatic, Retail/Commerce Media, Investment and Ad Operations.
 * Case data are simulated; platform access/menus are subject to account and market eligibility.
 */
var ROLE_GUIDES = ROLE_GUIDES || {};
ROLE_GUIDES.programmatic = {
 scope:"Programmatic Specialist mengelola pembelian inventory digital melalui DSP dan mekanisme auction/deal. Kompetensinya mencakup supply chain, OpenRTB, identity/privacy, DSP architecture, inventory/deals, bidding/pacing, verification, trafficking, measurement, and supply quality. Programmatic berbeda dari paid social/search dan berbeda dari Ad Ops; specialist ini mengambil keputusan buying dan delivery melalui platform programmatic.",
 workflow:["<b>Map the supply chain.</b> Pahami advertiser, agency, DSP, exchange, SSP, publisher ad server, data provider, and verification provider.","<b>Plan audience and inventory.</b> Pilih first-party/contextual/partner signals, deal type, formats, privacy basis, and supply-path controls.","<b>Build and activate.</b> Struktur campaign/IO/line item, creative, trackers, bidding, budget, frequency, and flight.","<b>Monitor quality and delivery.</b> Pacing, win rate, viewability, IVT, brand safety, deal delivery, and discrepancy.","<b>Evaluate and optimise.</b> Reconcile source data, measurement, marginal outcomes, supply quality, and post-campaign learnings."],
 qa:["Setiap impression melalui rangkaian buyer–DSP–exchange–SSP–publisher. Mapping fee, reseller, ads.txt/sellers.json, timeout, and deal terms membantu menemukan supply leakage dan risiko inventory.","Bid strategy harus mempertimbangkan goal, CPM floor, auction dynamics, audience signal, budget, win rate, and frequency. Jangan mengubah bid tanpa melihat delivery, inventory, and conversion signal.","Quality tidak cukup dinilai dari CPM/CTR. Periksa viewability definition, eligible/measurable impressions, IVT filtering, brand suitability, publisher transparency, and outcome."],
 glossary:[["DSP","Platform sisi pembeli untuk merencanakan dan membeli digital inventory."],["SSP","Platform sisi publisher untuk mengelola dan menjual inventory."],["Ad exchange","Marketplace yang menghubungkan demand dan supply."],["OpenRTB","Standar protokol untuk pertukaran bid request/response."],["SPO","Supply Path Optimization."],["PMP","Private Marketplace deal."],["PG","Programmatic Guaranteed."],["Viewability","Pengukuran apakah iklan memenuhi kriteria terlihat."],["IVT","Invalid Traffic."],["Floodlight","Tag/activity measurement dalam Campaign Manager 360."]],
 chapters:[
  {concept:"Programmatic advertising mengotomasi pembelian inventory digital melalui platform dan auction. DSP mengelola demand; SSP membantu publisher mengelola supply; exchange menghubungkan keduanya; ad server mengatur delivery. Peran dan biaya tiap intermediary perlu dipahami karena berdampak pada transparency, latency, quality, and net media value.",example:"SIMULASI — advertiser membelanjakan Rp100 juta melalui DSP, tetapi report publisher dan DSP menunjukkan volume berbeda. Tim memetakan fee, exchange, SSP, reseller, and ad server untuk mengetahui perbedaan basis delivery.",actions:["Gambar alur advertiser → agency → DSP → exchange → SSP → publisher/ad server.","Tandai data, fee, control, and responsibility at every node.","Bandingkan DSP reporting dengan publisher proof and contract basis."],practice:"Buat supply-chain map yang menyebut platform, owner, data exchanged, cost/fee, transparency evidence, and failure points. Sertakan satu sample impression flow.",qaFocus:["membedakan DSP, SSP, exchange, dan ad server","menjelaskan peran tiap intermediary dalam impression flow","memetakan di mana fee dan data visibility berkurang"],terms:[["Supply chain","Rangkaian teknologi dan pihak dalam transaksi inventory."],["Bid request","Permintaan data/parameter untuk sebuah kesempatan iklan."],["Bid response","Tawaran dari buyer kepada auction."]]},
  {concept:"RTB adalah proses lelang per kesempatan impression. OpenRTB menstandarkan struktur bid request/response agar buyer dan seller dapat bertukar informasi tentang placement, device, user/context signals, and auction. Supply Path Optimization mengevaluasi jalur supply berdasarkan transparency, fees, duplication, quality, latency, and authorised sellers.",example:"SIMULASI — dua jalur mengakses publisher yang sama: direct SSP dan beberapa reseller. Jalur reseller memiliki fee dan latency lebih tinggi tanpa added value. SPO analysis membantu memilih route yang lebih efisien.",actions:["Uraikan bid request → DSP evaluation → bid response → auction → ad serve.","Kenali field OpenRTB relevan seperti impression, site/app, device, user/context, and deal.","Audit seller chain, ads.txt, sellers.json, fee, duplication, and timeout."],practice:"Buat annotated OpenRTB bid request/response sederhana (synthetic JSON), supply-path diagram, and SPO comparison matrix. Jangan mengirim bid sungguhan.",qaFocus:["menjelaskan urutan RTB dan informasi dalam bid request","mengidentifikasi data fields yang sensitif atau tidak tersedia","menilai SPO dengan transparency, fees, duplication, dan quality"],terms:[["RTB","Real-time bidding."],["Supply Path Optimization","Evaluasi jalur supply untuk transparency dan efficiency."],["sellers.json","File untuk mengidentifikasi entitas yang menjual inventory melalui supply chain."]]},
  {concept:"Audience/data strategy menilai sumber first-party, contextual, and permitted partner signals. Identity solutions tidak selalu mengidentifikasi individu secara deterministik; coverage berbeda menurut browser, environment, and consent. Privacy and signal loss harus menjadi bagian desain campaign, bukan sekadar catatan setelah targeting.",example:"SIMULASI — target customer CRM memiliki consent untuk channel tertentu tetapi belum tentu untuk third-party audience activation. Specialist memisahkan eligible first-party use, contextual targeting, and non-eligible data.",actions:["Klasifikasikan source: advertiser first-party, platform, contextual, partner, or modeled.","Periksa provenance, consent, purpose limitation, retention, and activation permission.","Buat audience coverage/overlap hypothesis dan privacy risk log."],practice:"Rancang data and audience strategy: data source, purpose, consent, identity limitation, segment, match/coverage assumption, activation path, suppression, and measurement.",qaFocus:["membedakan first-party, contextual, partner, and inferred signals","membuktikan dasar penggunaan data sesuai consent/purpose","menjelaskan signal loss dan identity coverage limits"],terms:[["First-party data","Data yang dikumpulkan langsung oleh organisasi dari interaksinya."],["Contextual targeting","Penargetan berdasarkan konteks konten/placement."],["Identity graph","Sistem yang menghubungkan identifier; kualitas dan coverage bergantung data/consent."]]},
  {concept:"Inventory mencakup display, video, CTV, audio, DOOH, native, and in-app. Deal types menentukan harga, akses, auction, delivery commitment, and operational rights. Open auction biasanya terbuka; PMP/preferred memberi akses/terms yang dinegosiasikan; Programmatic Guaranteed mereservasi delivery sesuai kesepakatan. Evaluate inventory according to audience, viewability, brand safety, and objective.",example:"SIMULASI — brand ingin reach premium audience melalui CTV dan video online. PMP dapat meningkatkan inventory control tetapi minimum commitment dan CPM lebih tinggi. Planner membandingkan open auction vs PMP vs PG.",actions:["Build inventory taxonomy by screen, format, environment, and publisher.","Compare deal type, floor/rate, commitment, delivery, targeting, and cancellation terms.","Match format and environment to objective and creative assets."],practice:"Buat inventory/deal matrix mencakup display, video, CTV, audio, DOOH; bandingkan open auction, PMP, preferred, and PG pada cost, control, commitment, risk, and use case.",qaFocus:["membedakan open auction, PMP, preferred, dan PG","memilih format berdasarkan audience dan tujuan","membaca komitmen delivery dan deal terms"],terms:[["Open auction","Auction inventory yang dapat diakses buyer eligible."],["Preferred deal","Kesepakatan harga/akses yang tidak selalu menjamin volume."],["Programmatic Guaranteed","Deal dengan harga dan delivery commitment yang disepakati."]]},
  {concept:"DSP architecture mengorganisasi advertiser, campaign, IO, line item, audience, inventory, creative, bid, budget, frequency, and reporting. DV360 menjadi platform latihan utama; TTD dan Amazon DSP dapat dibandingkan sebagai contoh environment lain. Menu, product naming, and access vary by contract and market; screenshot latihan harus berasal dari demo/account yang memang boleh diakses.",example:"SIMULASI — satu advertiser memiliki campaign awareness dan retargeting dengan budget, audience, and KPI berbeda. Struktur line item harus menjaga kontrol tanpa memecah data secara berlebihan.",actions:["Map advertiser/campaign/IO/line item/creative/audience relationships.","Identify required settings, permissions, pixels, and reporting levels.","Compare DV360/TTD/Amazon DSP concepts without assuming UI or access is identical."],practice:"Buat annotated DSP blueprint untuk DV360: advertiser, campaign, IO, line item, targeting, bidding, creative, tracking, and report. Jika tidak punya account access, gunakan workflow mockup dan labeli draft/demo.",qaFocus:["memahami hierarchy pada DSP","menentukan unit struktur sesuai budget/objective/targeting","membedakan platform UI screenshot asli dengan conceptual mockup"],terms:[["IO","Insertion Order pada platform buying."],["Line item","Unit konfigurasi delivery, targeting, bid, and budget."],["DSP seat","Akun/akses buyer yang mengelola media buying di DSP."]]},
  {concept:"Campaign structure dan trafficking menyiapkan flight, audience, inventory, creative, landing URL, macro, tracking, and naming. Creative format must meet publisher requirements, file size, duration, click destination, SSL, and fallback. Before launch, verify every placement/line item is mapped correctly; otherwise ad can serve wrong creative or lose measurement.",example:"SIMULASI — 300×250 display creative is uploaded to a video placement; URL macros are missing; tags fire but click reporting is incorrect. A trafficking sheet and preflight prevent these operational failures.",actions:["Build campaign structure and naming taxonomy.","Map creative specs, placement, URL/macro, tracker, and landing page.","Review QA evidence and publisher acceptance before launch."],practice:"Buat programmatic trafficking sheet dengan IO/line item, dates, audience, inventory, bid, budget, creative dimensions/file, URLs/macros, trackers, owner, QA status, and approval.",qaFocus:["memvalidasi asset/spec dan placement mapping","menjaga macro dan tracking parameter","menyimpan prelaunch QA dan approval"],terms:[["Trafficking","Proses konfigurasi campaign/ads/tags untuk delivery."],["Macro","Token dinamis yang diisi sistem pada URL/tag."],["Fallback creative","Aset cadangan jika format utama gagal dirender."]]},
  {concept:"Bidding, budget pacing, and frequency management harus dikelola bersama. CPM bid, optimization goal, inventory, competition, conversion signal, and pacing mode memengaruhi delivery. Frequency capping membatasi overexposure, tetapi harus dilihat lintas placement/deal where possible. Sudden changes can reset learning or alter auction behavior.",example:"SIMULASI — campaign underspends by 30% despite high bid. Diagnosis checks audience size, deal inventory, floor, targeting, creative rejection, pacing, and budget. Raising bid without identifying bottleneck may waste spend.",actions:["Select bid strategy based on objective, available event signal, and volume.","Set daily/lifetime budget, pacing mode, floor/bid guardrails, and frequency caps.","Review spend, impressions, win rate, CPA, quality, and saturation together."],practice:"Buat bidding & pacing plan: objective, bid method, CPM/CPA assumptions, budget pacing, frequency cap, audience saturation, underdelivery triggers, and optimization actions.",qaFocus:["membedakan bidding issue dengan inventory/targeting constraint","mengelola pacing dan frequency bersama","menghubungkan bid decision dengan objective dan event signal"],terms:[["Pacing","Kecepatan konsumsi budget terhadap jadwal."],["Win rate","Proporsi bid yang menang dari eligible bid."],["Frequency cap","Batas jumlah exposure per user/periode."]]},
  {concept:"Private Marketplace, preferred deals, and Programmatic Guaranteed differ in access, priority, price, and delivery commitment. Deal ID, buyer eligibility, floor, audience, inventory, creative acceptance, timeout, and publisher rules must be aligned. Deal negotiation also requires operational readiness; a deal without proper mapping may not deliver despite an agreed price.",example:"SIMULASI — buyer receives a PMP Deal ID with a floor price and strict dates, but the wrong seat is authorized and campaign does not bid. Deal-ID hygiene and test impressions are required.",actions:["Compare deal types on price, exclusivity, priority, commitment, and risk.","Verify Deal ID, buyer seat, publisher/supply partner, floor, targeting, and dates.","Track negotiated terms, test delivery, underdelivery, and makegoods."],practice:"Buat deal proposal one-pager comparing PMP, preferred, and PG. Include terms, Deal ID validation, inventory, minimums, floor, commitment, creative QA, and fallback plan.",qaFocus:["memilih deal type sesuai control/delivery need","memvalidasi Deal ID, seat, floor, and dates","memastikan deal contract terms tercermin di campaign setup"],terms:[["Deal ID","Identifier untuk mengakses inventory melalui deal."],["Floor price","Harga minimum yang disyaratkan seller."],["Priority","Urutan/keutamaan delivery pada inventory/deal."]]},
  {concept:"Verification separates viewability, invalid traffic, brand safety, and brand suitability. MRC measurement standards define measurement principles; IAS and DoubleVerify provide commercial verification solutions. Supply quality also includes ads.txt, sellers.json, reseller chain, domain/app transparency, and exclusion controls. One metric never proves all quality dimensions.",example:"SIMULASI — CPM is low, but 18% of measured impressions are invalid and a significant share appears on unsuitable content. Campaign should be evaluated by valid eligible reach and risk, not cheap volume alone.",actions:["Define metric scope: measured/eligible impressions, viewability threshold, IVT type, and brand-suitability policy.","Review vendor coverage, exclusions, verification logs, and publisher/domain lists.","Audit authorised sellers and supply path; record exceptions."],practice:"Buat supply-quality audit report: inventory source, ads.txt/sellers.json, viewability, IVT, suitability, vendor methodology, coverage, exclusion, risk, and remediation.",qaFocus:["membedakan viewability, IVT, safety, dan suitability","membaca coverage/denominator pada verification report","menelusuri reseller chain dan authorized sellers"],terms:[["Viewability","Apakah impression memenuhi kriteria terlihat yang ditetapkan."],["IVT","Invalid traffic."],["Brand suitability","Kesesuaian lingkungan konten untuk nilai/risiko brand."]]},
  {concept:"CM360 and Floodlight connect ad serving and conversion measurement across campaigns. Understand advertiser/campaign/site/placement/ad/creative structure, tag types, Floodlight activities, counting methods, conversion windows, and attribution. DSP and CM360 report differences may come from event definitions, timezone, deduplication, attribution, latency, and tracking setup.",example:"SIMULASI — DSP reports 800 conversions, CM360 reports 720, and GA4 reports 650 sessions with purchase. The discrepancy is investigated through conversion definitions, windows, identity, and deduplication rather than declared as error.",actions:["Map DSP, CM360 placement/ad/creative, Floodlight activity, and event flow.","Verify tag implementation, click/impression trackers, event_id, consent, and conversion counting.","Reconcile reporting source, timezone, windows, latency, and billable definitions."],practice:"Buat CM360 measurement plan: campaign/placement/creative map, Floodlight activity, tags, conversion window, counting method, test cases, discrepancy rules, and source-of-truth policy.",qaFocus:["memahami relasi placement/ad/creative dan Floodlight","menentukan conversion counting sesuai kebutuhan","menginvestigasi discrepancy dengan definisi sepadan"],terms:[["Floodlight activity","Aktivitas konversi yang diukur dalam Campaign Manager 360."],["Counting method","Aturan berapa kali conversion dihitung."],["Deduplication","Proses menghindari event/conversion yang terhitung ganda."]]},
  {concept:"Optimization harus melihat spend, win rate, inventory quality, audience, creative, viewability, IVT, frequency, conversion signal, and marginal return. Reporting menjelaskan apakah campaign delivery sesuai plan, bagaimana kualitas supply, and what should change. Post-campaign supply review is distinct from generic ROAS reporting.",example:"SIMULASI — a line item has low CTR but high qualified conversion rate on premium context. Pausing solely on CTR may harm outcomes; segment by objective, audience, format, and contribution.",actions:["Check daily pacing and campaign health by line item and deal.","Diagnose audience/creative/inventory/auction/tracking before changing bid.","Compare cost, valid reach, conversion quality, and post-buy evidence."],practice:"Buat weekly optimization report and post-campaign supply review from synthetic data: issue, evidence, change, owner, guardrail, result, and next action.",qaFocus:["mengoptimalkan berdasarkan tujuan, bukan satu metrik","memisahkan supply/auction/creative/tracking diagnosis","mengukur kualitas inventory selain volume"],terms:[["Post-campaign analysis","Evaluasi setelah campaign selesai."],["Supply quality","Kualitas dan transparansi inventory sumber."],["Marginal performance","Perubahan outcome dari tambahan/pengurangan investasi."]]},
  {concept:"Capstone Programmatic menyatukan strategy, audience/data, inventory, deal selection, DSP setup, creative/trafficking, bidding, verification, measurement, discrepancy, and post-buy. Buat audit trail dari brief sampai final invoice/report. Semua hasil sintetis harus ditandai; jangan mengklaim akses ke DSP production bila hanya mockup.",example:"SIMULASI — brand automotive ingin reach in-market audience melalui online video/CTV dan retargeting dengan budget Rp250 juta. Peserta memilih inventory/deal, menyiapkan DSP blueprint, pacing, quality verification, and post-campaign review.",actions:["Frame objective and audience; choose supply and deal model.","Design DSP structure, bidding, creatives, tracking, and QA.","Monitor quality, reconcile performance, and present optimization decisions."],practice:"Buat capstone pack: DSP blueprint, inventory/deal matrix, supply-path audit, trafficking sheet, bid/pacing plan, verification settings, measurement map, discrepancy report, and executive review.",qaFocus:["menjaga konsistensi dari deal sampai serving and measurement","membuktikan quality control dan reconciliation","menjelaskan trade-off inventory, price, delivery, and outcomes"],terms:[["SPO","Supply Path Optimization."],["Programmatic guaranteed","Deal dengan delivery commitment."],["Capstone pack","Kumpulan bukti kerja yang memperlihatkan workflow end-to-end."]]}
 ]
};
ROLE_GUIDES.retail = {
 scope:"Retail & Commerce Media Specialist menghubungkan advertising dengan shopper behavior dan transaksi pada retailer/marketplace. Di Indonesia, kurikulum memprioritaskan Shopee Ads, TikTok Shop/Tokopedia, Lazada, dan Blibli. Amazon, Microsoft Retail, and global retail media dipakai sebagai pembanding global, bukan prasyarat untuk semua peserta Indonesia.",
 workflow:["<b>Understand shopper/category.</b> Pahami purchase intent, category role, basket, seasonality, price, and retailer context.","<b>Check retail readiness.</b> Audit product feed, title, image, content, rating/review, price, stock, availability, and fulfilment.","<b>Choose retailer and placement.</b> Match onsite/offsite/store media, audience data, category demand, and seller eligibility.","<b>Activate and optimise.</b> Structure product/store campaigns, bids, budgets, creative, and pacing.","<b>Measure commerce outcome.</b> ACoS/ROAS, incremental sales, new-to-brand, share, margin, return, and retailer reporting limits."],
 qa:["Pilih retailer berdasarkan market share/traffic yang relevan dengan kategori, audience, seller eligibility, stock, product availability, placement, and data access. Jangan memilih hanya karena platform besar atau promonya ramai.","Retail advertising tidak dapat mengatasi product-page issue secara otomatis. Feed, title, image, price, review, stock, buy-box/availability, and fulfilment memengaruhi conversion.","ROAS/ACoS platform adalah attributed metric menurut window dan model retailer. Untuk menilai business impact, periksa margin, organic baseline, new-to-brand, cannibalisation, holdout, and stock."],
 glossary:[["Retail Media Network","Media inventory yang dimiliki/dioperasikan retailer atau commerce platform."],["Onsite media","Iklan di properti digital retailer."],["Offsite media","Penggunaan retailer audience/data di luar properti retailer."],["Sponsored Product","Placement iklan yang mempromosikan item tertentu."],["Digital shelf","Kualitas product page, content, availability, ratings, and discoverability."],["Product feed","Data terstruktur mengenai produk dan atributnya."],["ACoS","Ad cost dibagi sales attributed."],["New-to-brand","Customer yang baru pertama kali membeli brand sesuai definisi retailer."],["Closed-loop measurement","Pengaitan exposure/ads dengan transaksi pada retailer."],["Incrementality","Tambahan outcome yang benar-benar disebabkan campaign."]
 ],
 chapters:[
  {concept:"Retail media tumbuh dari kemampuan retailer menggabungkan audience, shopper intent, onsite placement, and transaction signals. Bedakan retail media dari commerce media yang lebih luas. Pahami onsite, offsite, and in-store opportunities, revenue model, data rights, inventory ownership, and measurement limitations.",example:"SIMULASI — retailer memiliki sponsored search, product display, offsite audience, dan in-store screens. Advertiser harus memutuskan channel berdasarkan shopper context dan produk, bukan menyamakan semua placement dengan paid social.",actions:["Map retailer, media network, seller/brand, audience data, placements, and transaction signals.","Bedakan onsite/offsite/in-store roles and data access.","Catat commercial model, eligibility, reporting, and measurement boundaries."],practice:"Buat retail/commerce media ecosystem map untuk satu kategori: retailer, network, advertiser, seller, shopper journey, placement, data, revenue model, and closed-loop measurement.",qaFocus:["membedakan retail media dengan commerce media secara operasional","memetakan kepemilikan inventory dan data","menjelaskan kelebihan/limitasi closed-loop measurement"],terms:[["Retail media","Iklan yang dijual melalui retailer-owned/operated media inventory."],["Commerce media","Media yang memanfaatkan transaksi/audience commerce di lebih banyak konteks."],["Shopper","Individu dalam proses mencari, membandingkan, dan membeli produk."]]},
  {concept:"Shopper journey bergerak dari category discovery ke consideration, product comparison, cart, purchase, and repeat. Retail data dapat mengungkap category signals, basket, brand switch, and purchase intent, tetapi level data, freshness, and representativeness berbeda antar retailer. Insight harus diterjemahkan menjadi target, message, and placement.",example:"SIMULASI — kategori household cleaner memiliki search demand tinggi saat payday, tetapi conversion turun karena harga paket pesaing lebih rendah dan stok retailer tertentu terbatas.",actions:["Map discovery, search, compare, product page, cart, purchase, repeat, and service.","Review category, query, basket, brand, price, availability, and seasonality signals.","Identify shopper barrier and media opportunity with evidence."],practice:"Buat shopper journey map untuk satu kategori: trigger, search behavior, retailer, product comparison, price sensitivity, stock, content/review, media touchpoint, and friction.",qaFocus:["menghubungkan retailer insight ke momen shopper","membedakan purchase intent dengan sekadar page view","mencatat bias dan batas data retailer"],terms:[["Shopper journey","Rangkaian perilaku sebelum, saat, dan setelah pembelian."],["Category insight","Insight kebutuhan dan persaingan pada kategori produk."],["Basket analysis","Analisis produk yang dibeli dalam satu transaksi."]]},
  {concept:"Retailer media networks berbeda dalam audience, seller eligibility, placement, bidding, reports, and commercial model. Di Indonesia, bandingkan Shopee Ads, TikTok Shop/Tokopedia Product Shopping Ads, Lazada Sponsored Solutions, dan Blibli Bliklan. Amazon Sponsored Ads serta Microsoft Retail dipelajari sebagai global benchmark; jangan menganggap nomenclature/availability sama di tiap negara.",example:"SIMULASI — brand electronics ingin promosi di empat marketplace. Platform A punya sponsored search, platform B menghubungkan katalog dan TikTok Shop, platform C punya discovery placements, dan platform D punya Bliklan. Plan perlu mempertimbangkan audience, stock, fees, and report.",actions:["Audit eligibility, seller/account requirements, inventory, placements, and buying interface.","Bandingkan CPC/CPM, bidding controls, targeting, search/onsite/offsite, and data access.","Pisahkan Indonesia core platforms dari global elective platform."],practice:"Buat matrix Shopee, TikTok Shop/Tokopedia, Lazada, dan Blibli: ad format, campaign setup, billing/bid, targeting, reporting, seller eligibility, and evidence URL. Tambahkan Amazon sebagai global comparator.",qaFocus:["membandingkan empat platform retail Indonesia","membedakan global elective dari platform wajib lokal","memeriksa nomenclature, seller eligibility, dan ad product availability"],terms:[["Retailer media network","Media platform yang dimiliki/dioperasikan retailer."],["Sponsored placement","Posisi iklan yang dipromosikan di property retailer."],["Seller eligibility","Syarat akun/produk untuk dapat beriklan."]]},
  {concept:"Onsite retail media menempatkan sponsored products, sponsored search, and store/product placements di retailer property. Keyword, category targeting, product match, bid, budget, and item availability menentukan peluang tampil. Product ad harus diarahkan ke item yang benar, stock-available, compliant, and ready to convert.",example:"SIMULASI — seller menawar keyword 'sunscreen SPF50' tetapi product page memiliki image/title yang tidak menyebut SPF. Traffic datang namun purchase rendah. Feed dan digital shelf harus diperbaiki sebelum menaikkan bid.",actions:["Map search terms/keywords to products and category intent.","Check bid, placement, item eligibility, stock, and product page readiness.","Create campaign/ad-group/product structure with budget and naming rules."],practice:"Buat onsite campaign plan: keyword/product mapping, bid, budget, placement, SKU, price/stock, content readiness, negative/irrelevant terms, and optimisation rules.",qaFocus:["memastikan keyword, product, dan intent cocok","mengecek stok/product page sebelum mengaktifkan sponsored ad","membedakan bidding problem dengan product-page friction"],terms:[["Sponsored Products","Iklan produk berbayar pada hasil pencarian/placement retailer."],["SKU","Stock Keeping Unit untuk mengidentifikasi item."],["Product targeting","Penargetan berdasarkan produk/kategori atau atribut item."]]},
  {concept:"Offsite retail media menggunakan audience/commerce signals retailer untuk reach di luar owned property melalui display, social, video, or programmatic inventory. Integrasi membutuhkan privacy permission, audience activation path, measurement agreement, and deduplication. Closed-loop sales may show attribution, not automatically incremental effect.",example:"SIMULASI — retailer audience dipakai untuk social video campaign yang mengarahkan audience ke product detail. Perlu bandingkan exposed vs control dan pastikan audience/data rights jelas.",actions:["Define audience eligibility and activation permission.","Choose offsite channel, format, frequency, landing destination, and retailer measurement.","Design conversion windows, holdout/experiment, and deduplication notes."],practice:"Buat offsite retail media plan dengan audience segment, platform, creative, placement, budget, retailer data permission, conversion measurement, and incrementality test.",qaFocus:["membedakan offsite audience activation dari onsite sponsored search","memastikan data sharing and consent","menafsirkan closed-loop attributed sales dengan caution"],terms:[["Offsite activation","Aktivasi audience retailer pada inventory di luar properti retailer."],["Closed-loop sales","Sales yang dihubungkan ke exposure/advertising di retailer."],["Audience suppression","Mengecualikan kelompok tertentu untuk mengurangi waste/overlap."]]},
  {concept:"Retail first-party data dapat mengelompokkan shopper berdasarkan category, brand affinity, recency, purchase, loyalty, and basket. Aktivasi harus mengikuti data-sharing terms, consent, purpose, retention, and platform policy. Audience segments should be large and stable enough for activation; avoid implying exact individual identity where retailer only offers aggregated or modeled segments.",example:"SIMULASI — segment 'category buyers in last 90 days' tersedia sebagai aggregated retailer audience. Advertiser tidak menerima raw customer details. Plan harus menghormati activation limits dan tidak mengklaim ownership data.",actions:["Define segment logic, recency, purchase, category, and exclusions.","Confirm privacy, consent, contract, activation destination, and measurement rights.","Estimate reach/overlap and test data freshness and segment availability."],practice:"Buat audience activation plan untuk tiga segment retailer: purpose, logic, eligible data, size/range assumption, privacy/permission, placement, suppression, measurement, and risk.",qaFocus:["membedakan segment rule dengan data yang benar-benar tersedia","memastikan use purpose and sharing permission","menyatakan ukuran/coverage audience sebagai estimate bila data terbatas"],terms:[["First-party retail data","Data transaksi/interaksi yang dimiliki retailer dari customer relationship."],["Loyalty segment","Kelompok berdasarkan keanggotaan/aktivitas loyalty."],["Data clean room","Environment terbatas untuk analisis/aktivasi data lintas pihak tanpa saling membuka raw data."]]},
  {concept:"Product feed dan digital shelf menentukan apakah produk mudah ditemukan, dipahami, dan dibeli. Audit judul, atribut, kategori, gambar, deskripsi, rating, review, price, stock, delivery, and promotion. Ads traffic cannot compensate for inaccurate product information or poor availability. Feed freshness and product eligibility need operational ownership.",example:"SIMULASI — campaign mendapat click tetapi conversion jatuh karena harga di iklan berbeda dengan product page dan stock status tidak diperbarui. Digital shelf QA harus menjadi launch requirement.",actions:["Audit product title, category, attributes, image/video, description, price, stock, ratings, and shipping.","Check feed accuracy, update cadence, duplicate SKU, and moderation status.","Score product readiness and fix critical issues before media activation."],practice:"Audit lima SKU: feed completeness, title, image, attribute, stock, price, rating/review, shipping, policy, and digital-shelf score. Prioritaskan perbaikan berdasarkan impact.",qaFocus:["mengidentifikasi feed error yang memengaruhi eligibility","membedakan media issue dengan readiness issue","menguji sinkronisasi price dan stock"],terms:[["Digital shelf","Pengalaman produk pada halaman retailer/marketplace."],["Product feed","Dataset atribut produk untuk katalog/ads."],["Availability","Ketersediaan item untuk dibeli dan dipenuhi."]]},
  {concept:"Campaign activation and optimization harus mempertimbangkan perbedaan setup tiap platform. Product-level bidding, store-level bidding, GMV Max, sponsored placements, and reporting interfaces are not identical. Mulai dari objective dan item eligibility, lalu optimasi bid/budget/creative berdasarkan ROAS, ACoS, stock, margin, and new-to-brand as available.",example:"SIMULASI — ACoS terlihat membaik setelah budget dipotong, tetapi sales total juga turun dan organic ranking berubah. Evaluasi perlu melihat incrementality, product availability, and overall contribution.",actions:["Follow platform-specific setup and policy; record account/seller eligibility.","Set campaign grouping, SKU, keywords, bids, budget, placements, and schedule.","Create weekly routine for spend, orders, ACoS/ROAS, stock, and product quality."],practice:"Buat platform activation playbook untuk dua marketplace: setup sequence, SKU mapping, bidding, budget, target, launch QA, pacing, optimization, and rollback/hold criteria.",qaFocus:["membedakan mechanics dan optimisation controls antar platform","menghindari penerapan strategi bidding yang sama tanpa validasi","memasukkan stock/margin ke keputusan media"],terms:[["GMV Max","Campaign/product advertising product name used in TikTok Shop ecosystem; confirm current availability."],["ACoS","Spend dibagi attributed ad sales."],["ROAS","Attributed sales value dibagi ad spend."]]},
  {concept:"ACoS and ROAS help describe attributed efficiency but do not reveal profit or incrementality alone. Add contribution margin, new-to-brand, repeat purchase, returns, and retailer organic baseline where possible. Measurement windows and lookback differ by marketplace, and platform dashboards may not be directly comparable.",example:"SIMULASI — campaign A has 8x attributed ROAS but mainly captures brand searches; campaign B has 4x ROAS and recruits new-to-brand customers. The better investment depends on margin, growth objective, and incremental contribution.",actions:["Define metric formula, attribution window, sales basis, returns, and currency.","Read ACoS/ROAS with margin, organic baseline, new-to-brand, and stock.","Plan holdout or matched comparison where possible to estimate incrementality."],practice:"Buat retail media measurement plan: ACoS, ROAS, TACoS, new-to-brand, margin, returns, sales window, data source, attribution limitation, and holdout/incrementality hypothesis.",qaFocus:["membedakan attributed efficiency dengan incremental impact","menentukan denominator dan lookback window","menilai sales quality, margin, and stock impact"],terms:[["TACoS","Total advertising cost divided by total sales."],["New-to-brand","Customer baru bagi brand menurut definisi platform."],["Incrementality test","Metode untuk memperkirakan tambahan outcome akibat advertising."]]},
  {concept:"Capstone menggabungkan shopper insight, retailer choice, onsite/offsite plan, product readiness, bidding, audience, measurement, and commercial rationale. Portfolio harus menunjukkan perbedaan antar platform Indonesia dan menyebut keterbatasan akses akun, data, and eligibility. Amazon/Microsoft dapat menjadi global comparator, bukan dipaksakan sebagai default Indonesia.",example:"SIMULASI — kategori household care ingin memperbesar trial di Shopee, TikTok Shop/Tokopedia, Lazada, dan Blibli. Setiap platform diberi role berdasarkan audience, placement, data, and seller readiness.",actions:["Choose category, target, shopper journey, and retailer selection.","Build onsite/offsite campaign, feed readiness, bid/budget, and schedule.","Design measurement, contribution, incrementality, reporting, and optimisation."],practice:"Buat capstone commerce media strategy: platform matrix, shopper journey, product/feed audit, media plan, bidding sheet, budget, KPI, measurement limitations, and 90-day optimization roadmap.",qaFocus:["menjelaskan mengapa platform dipilih untuk target market","menjaga product readiness dan media activation dalam satu plan","memisahkan attributed ROAS dari contribution/incrementality"],terms:[["Commerce media strategy","Rencana media yang menghubungkan retailer/commerce touchpoint dan outcome."],["Assortment","Kumpulan SKU/varian produk yang tersedia."],["Media incrementality","Tambahan penjualan yang terjadi karena investasi media."]]}
 ]
};
ROLE_GUIDES.investment = {
 scope:"Media Buying, Investment & Publisher Partnerships menangani sisi komersial pembelian media langsung: media owner, inventory valuation, RFP/RFQ, proposal, rate benchmarking, negotiation, terms, booking/IO, delivery proof, makegood, invoice, and investment evaluation. Role ini berbeda dari Media Planning (menentukan mix) dan Programmatic Trading (auction via DSP).",
 workflow:["<b>Map supply and partners.</b> Kenali media owner, publisher, sales house, rep, reseller, inventory, audience, and sales model.","<b>Evaluate value.</b> Bandingkan audience quality, context, reach, rates, availability, added value, and proof methodology.","<b>Run procurement.</b> Buat RFP/RFQ, apples-to-apples matrix, benchmark, commercial terms, and negotiation plan.","<b>Book and govern.</b> Terbitkan IO/contract, approvals, cancellation, exclusivity, taxes, delivery commitments, and makegood clauses.","<b>Reconcile investment.</b> Monitor actual delivery, proof, invoices, credits, makegoods, and post-buy value."
 ],
 qa:["Bandingkan proposal dengan basis seragam: unit, audience, dates, geography, gross/net, taxes, fees, bonus, sponsorship rights, measurement, cancellation, and delivery proof. Harga rendah tidak otomatis value tinggi.","Negosiasi harus mengejar value dan risk allocation, bukan hanya discount. Catat floor/ceiling, alternatives, trade-offs, added value, exclusivity, cancellation, makegood, and service levels.","Rekonsiliasi invoice harus mengikuti IO dan proof-of-performance yang disepakati. Cocokkan booking, delivered units, billable basis, currency, tax, discount, bonus, credit, and makegood."],
 glossary:[["Media owner","Entitas yang memiliki atau menjual inventory media."],["Media kit","Dokumen publisher tentang audience, format, inventory, rate, and policies."],["RFP/RFQ","Request for Proposal/Quotation."],["Rate card","Daftar harga komersial untuk inventory."],["IO","Insertion Order / dokumen booking."],["Makegood","Kompensasi atas delivery yang tidak terpenuhi."],["Value-add","Added media/service value di luar core booking."],["Principal media","Model pembelian/penjualan inventory dengan peran principal pada transaksi."],["Rebate","Kredit/kompensasi komersial menurut kontrak."],["Proof of performance","Evidence delivery sesuai booking."]
 ],
 chapters:[
  {concept:"Media buying dimulai dari landscape media owner dan supply. Bedakan publisher, broadcaster, OOH operator, sales house, reseller, agency, and trading desk. Media kit dan proposal harus diperiksa dari audience methodology, inventory, format, availability, pricing basis, and proof. Jangan menyamakan direct publisher buying dengan programmatic auction.",example:"SIMULASI — brand menerima proposal direct publisher, sales house, dan agency reseller untuk inventory serupa. Perbandingan harus mengungkap siapa penjual sebenarnya, fee, rights, audience methodology, and delivery accountability.",actions:["Map media owners and sales representation for the category.","Read media kit, audience universe, format, rate, availability, and policy.","Identify transaction path, intermediary, fee, and delivery owner."],practice:"Buat media-owner map untuk satu kategori: publisher, broadcast, OOH, print, cinema, audio, digital, sales house, sales contact, audience data, inventory, and commercial notes.",qaFocus:["membedakan media owner dengan sales representative/reseller","menilai kualitas media kit dan audience methodology","menentukan pihak yang bertanggung jawab atas delivery"],terms:[["Publisher","Penerbit/pemilik properti konten dan inventory."],["Sales house","Perwakilan komersial yang menjual inventory."],["Reseller","Pihak yang menjual kembali inventory pihak lain."]]},
  {concept:"Inventory assessment menilai nilai media melalui audience relevance, context, attention, format, reach, quality, scarcity, placement, and brand safety. Price must be compared with value and delivery conditions. Availability and timing matter; premium sponsorship may be valuable but not scalable, while remnant inventory may carry quality or adjacency risk.",example:"SIMULASI — publisher menawarkan homepage takeover 1 hari dengan audience kecil tetapi contextual relevance tinggi; opsi kedua menawarkan banner run-of-site volume besar. Nilai dibandingkan berdasarkan objective, attention, audience, and proof.",actions:["Compare audience relevance, quality, format, context, reach, and scarcity.","Check availability, exclusivity, adjacency, viewability/measurement, and proof.","Create weighted value score and document non-comparable attributes."],practice:"Buat inventory assessment sheet untuk tiga opsi media: audience, context, placement, format, rate, availability, proof, risk, added value, and decision rationale.",qaFocus:["menjelaskan value beyond rate","membedakan inventory quantity dengan audience quality","menilai availability dan timing sebagai commercial constraint"],terms:[["Premium inventory","Placement bernilai tinggi karena audience/context/positioning."],["Run of site","Pembelian inventory lintas halaman/site sesuai ketentuan."],["Added value","Benefit tambahan yang diberikan dalam deal."]]},
  {concept:"RFP/RFQ menetapkan scope agar vendor memberi proposal yang bisa dibandingkan. Spesifikasi harus mencakup objective, target, dates, geography, formats, volumes, pricing units, measurement, reporting, brand safety, cancellation, and terms. Evaluation matrix menghindari keputusan berdasarkan presentasi paling menarik tanpa komersial setara.",example:"SIMULASI — tiga publisher menjawab brief awareness dengan CPM, sponsorship, and package berbeda. RFP perlu standard units, gross/net, taxes, and audience definitions agar perbandingan apple-to-apple.",actions:["Write an RFP brief with scope, objectives, deliverables, terms, and evaluation criteria.","Specify response templates: rate, volume, audience, formats, availability, measurement, and exclusions.","Score proposal on value, delivery confidence, risk, and commercial fit."],practice:"Buat RFP draft dan proposal evaluation matrix untuk tiga vendor. Sertakan pricing unit, tax, fee, audience basis, delivery guarantee, measurement, cancellation, and selection rationale.",qaFocus:["menulis RFP agar proposal dapat dibandingkan setara","mengidentifikasi biaya/terms yang tersembunyi","menggunakan evaluation criteria yang disepakati sebelum proposal dinilai"],terms:[["RFP","Request for Proposal."],["RFQ","Request for Quotation."],["Apples-to-apples","Perbandingan dengan basis definisi dan scope yang sama."]]},
  {concept:"Commercial benchmarking membandingkan rate, net cost, audience value, added value, package, sponsorship, and delivery commitment. CPM is not enough for every media type; compare CPP, cost per reach, sponsorship rights, share of voice, or qualified audience where appropriate. Record period, geography, negotiation basis, and whether tax/fees are included.",example:"SIMULASI — vendor offers 20% discount plus bonus impressions. Setelah dinormalisasi, bonus inventory mungkin memiliki placement dan audience quality berbeda; net effective price perlu dihitung dari value yang sebanding.",actions:["Normalize rates, units, period, geography, gross/net, taxes, and fees.","Compare benchmarks with audience and placement quality.","Separate paid value, bonus value, and contractual delivery."],practice:"Bangun rate benchmarking workbook untuk tiga vendor: rate card, quoted rate, net rate, CPM/CPP where valid, bonus, taxes, added value, and confidence source. Data harus SIMULATED bila bukan quote real.",qaFocus:["menghitung benchmark dengan unit/period setara","memisahkan diskon dari bonus inventory","menghindari membandingkan format dengan metric berbeda"],terms:[["Effective CPM","Biaya per seribu impressions berdasarkan basis yang disepakati."],["CPP","Cost per rating point."],["Bonus inventory","Delivery tambahan di luar paid booking."]]},
  {concept:"Negosiasi media memadukan leverage, alternatives, timing, inventory value, and relationship. Trading terms memuat cancellation, makegood, exclusivity, first refusal, rebates, payment, credit, service levels, data, creative responsibility, and dispute process. Relationship management tidak menggantikan written terms; semua komitmen perlu dicatat.",example:"SIMULASI — vendor offers discount if brand commits to a quarterly package. Brand compares opportunity cost, cancellation terms, delivery proof, and ability to shift budget if performance changes.",actions:["Set negotiation objectives, BATNA, walk-away conditions, and value priorities.","Prepare counterproposal on rate, bonus, inventory, terms, and measurement.","Record agreed terms, owners, deadlines, and contract changes."],practice:"Buat negotiation plan dengan opening, target, walk-away, BATNA, concessions, value-add, risk terms, and post-meeting confirmation email. Simulasikan vendor negotiation.",qaFocus:["menentukan BATNA dan trade-offs sebelum negosiasi","membedakan verbal agreement dengan written contract","menilai biaya exclusivity dan cancellation"],terms:[["BATNA","Best Alternative to a Negotiated Agreement."],["Exclusivity","Pembatasan bekerja dengan pihak/brand tertentu."],["Cancellation clause","Ketentuan pembatalan booking dan konsekuensi biayanya."]]},
  {concept:"IO and contract terms translate the agreement into an executable booking. Fields typically include advertiser, agency, vendor, campaign, placement, rate, units, date, tax, billing, payment, cancellation, makegood, and approval. Booking workflow needs version control and authorization; no placement should be assumed confirmed without a valid IO/acceptance.",example:"SIMULASI — IO has wrong campaign dates and gross/net basis compared with approved proposal. Vendor begins delivery; financial reconciliation later becomes disputed. Pre-booking check prevents this.",actions:["Map proposal terms to IO fields and confirm all commercial bases.","Check dates, formats, units, pricing, tax, cancellation, payment, and makegood.","Get documented approvals and vendor acceptance; track version changes."],practice:"Buat sample IO draft (clearly marked simulated) and a contract-review checklist. Cross-check every line against approved proposal and approval trail.",qaFocus:["memastikan IO sama dengan proposal dan approval","mengidentifikasi terms yang berpengaruh pada billable delivery","menjaga version control dan authorization"],terms:[["IO","Insertion Order."],["Booking confirmation","Konfirmasi vendor atas order media."],["Approval trail","Rekaman siapa yang menyetujui keputusan/dokumen."]]},
  {concept:"Campaign delivery should be compared with contract units and proof-of-performance. Monitoring identifies underdelivery, makegood eligibility, placement changes, cancellation, and proof gaps. Do not accept a screenshot alone if contract requires platform report, log, URL, play-out certificate, or third-party verification. Evidence needs date, placement, volume, and agreed metric.",example:"SIMULASI — booked 10 million display impressions but publisher delivers 8.7 million. IO has a delivery tolerance and makegood clause. Buyer calculates shortfall and requests remediation under contract terms.",actions:["Set planned delivery checkpoints and proof requirements before launch.","Compare delivered vs booked by day, placement, audience, and unit.","Open shortfall case with calculation, contract clause, and remedy request."],practice:"Buat delivery-monitoring log and makegood case note using synthetic booking/delivery data. Cite the IO clause and calculate shortfall/remedy.",qaFocus:["menggunakan proof sesuai kontrak","menghitung underdelivery pada basis yang benar","mengajukan makegood berdasarkan clause, not assumption"],terms:[["Proof of performance","Bukti delivery/penayangan yang dapat diaudit."],["Shortfall","Selisih delivery aktual dari komitmen."],["Makegood","Remedy untuk delivery yang tidak terpenuhi."]]},
  {concept:"Invoice reconciliation connects approved IO, delivery proof, rate, billable units, currency, tax, discount, bonus, credits, and makegood. Finance control requires traceable documents, segregation of duties, period cutoff, and exception management. A delivered report may not be the contractual billing basis; confirm before disputing invoices.",example:"SIMULASI — invoice uses gross rate and includes tax while the planning sheet compares net media. Difference is not necessarily error; reconcile currency, fee, tax, billable metric, discount, and terms.",actions:["Match invoice lines to IO and approved amendments.","Check billable units, rate, period, currency, tax, discounts, credits, and makegoods.","Record variance, owner, resolution, and supporting evidence."],practice:"Buat reconciliation worksheet from synthetic IO, delivery report, invoice, credit note, and makegood. Include variance calculation and audit evidence index.",qaFocus:["mencocokkan invoice dengan IO dan proof-of-performance","memisahkan gross/net, tax, fee, and currency","mencatat exception hingga resolution"],terms:[["Reconciliation","Pencocokan dokumen/angka antar sistem."],["Billable basis","Unit yang menurut kontrak menjadi dasar tagihan."],["Credit note","Dokumen penyesuaian/pengurang invoice."]]},
  {concept:"Post-buy evaluation menilai cost, delivery, quality, negotiated value, audience, and business contribution. Investment efficiency may include effective CPM/CPP, cost per reach, cost per qualified action, added value realization, and supplier performance. Recommendations can cover vendor mix, negotiation, booking terms, and inventory choices for the next cycle.",example:"SIMULASI — vendor A delivered on time but had high discrepancy; vendor B had stronger audience quality and delivered a lower effective cost after bonus normalisation. Recommendation weighs performance and service risk.",actions:["Compare booked vs delivered value and service performance.","Normalize actual costs and evaluate value-add realization.","Prepare vendor scorecard and next-cycle recommendation."],practice:"Buat post-buy evaluation memo: commercial performance, delivery, quality, variance, service, risks, supplier score, and next-cycle action.",qaFocus:["menilai deal dengan biaya dan value yang benar-benar delivered","membedakan effective cost dengan rate card","memberi rekomendasi vendor/terms berbasis evidence"],terms:[["Post-buy","Evaluasi komersial setelah campaign berjalan."],["Vendor scorecard","Penilaian supplier berdasarkan cost, quality, delivery, and service."],["Effective cost","Biaya aktual berdasarkan value/delivery yang diterima."]]},
  {concept:"Capstone meniru pekerjaan Media Investment dari market mapping sampai invoice close. Peserta harus menunjukkan procurement logic, negotiation preparation, contract control, delivery evidence, financial reconciliation, and post-buy. This role is commercial governance, not a substitute for media planning or DSP operation.",example:"SIMULASI — brand consumer menegosiasikan paket media multi-vendor 3 bulan dengan budget Rp2 miliar. Deliverable harus menunjukkan procurement transparency, documented trade-offs, and billable proof.",actions:["Map owners and evaluate inventory/proposals.","Negotiate and document rates, terms, IO, approval, and bookings.","Monitor delivery, reconcile invoice, and recommend next investment."],practice:"Buat investment case pack: vendor map, RFP, proposal matrix, negotiation plan, IO draft, delivery log, makegood claim, reconciliation, and executive post-buy recommendation. Tandai seluruh angka SIMULATED.",qaFocus:["menyatukan procurement, negotiation, booking, and financial control","menjaga audit trail dari proposal ke invoice","menjelaskan trade-off komersial dan rekomendasi next cycle"],terms:[["Investment case","Dokumen justifikasi pembelian/investasi media."],["Commercial governance","Aturan approval, terms, documentation, and financial control."],["Audit trail","Jejak bukti keputusan dan transaksi."]]}
 ]
};
ROLE_GUIDES.adops = {
 scope:"Ad Operations / Digital Campaign Operations mengubah approved media plan menjadi setup teknis yang aman untuk live: account/placement, trafficking, creative spec, tags/pixels/UTM, CM360/Floodlight, platform-native ad setup, preflight, monitoring, discrepancy, billing handoff, and documentation. Ad Ops bersifat lintas platform—Google, Meta, TikTok, DSP/ad server—tetapi kedalaman tiap tool mengikuti tugas dan akses akun.",
 workflow:["<b>Intake and translate.</b> Baca brief/IO/media plan, ownership, campaign dates, targeting, budget, creative, URL, tags, and approval.","<b>Configure and traffic.</b> Susun campaign/placement/ad, creative assignment, naming, parameters, tracking, and platform settings.","<b>Preflight and validate.</b> Test click, impression, event, rendering, targeting, consent, and publisher acceptance.","<b>Monitor and troubleshoot.</b> Check pacing, delivery, rejection, tag, creative, discrepancy, and escalation.","<b>Close and document.</b> Reconcile proof/billing, archive versions, capture incidents, and process improvement."],
 qa:["Trafficking sheet harus menjadi single source of truth: campaign/placement/ad, dates, budget, audience, creative, URL, tags, macros, owner, approvals, and status. Perubahan wajib versioned; jangan mengandalkan chat pribadi.","QA dilakukan end-to-end: rendering, click destination, tracking, events, parameters, targeting, schedule, budget, consent, and platform policy. Simpan expected vs actual, timestamp, browser/device, owner, and severity.","Discrepancy baru dapat dinyatakan error setelah event definition, timezone, attribution window, click/view rule, deduplication, latency, billable basis, and contract are aligned."],
 glossary:[["Trafficking","Penerjemahan media plan menjadi setup teknis campaign/placement/ad."],["Placement","Unit inventory/slot yang menerima iklan pada ad server."],["Floodlight","Conversion/activity measurement pada Campaign Manager 360."],["Tag","Script/URL/pixel yang mengirim event atau tracking signal."],["UTM","Parameter URL untuk mengidentifikasi source/medium/campaign."],["Macro","Token dinamis yang mengisi parameter pada click/impression URL."],["Preflight QA","Pengujian sebelum campaign live."],["Discrepancy","Selisih angka antar sistem yang perlu direkonsiliasi."],["Pacing","Kecepatan spend/delivery terhadap rencana."],["Makegood","Remedy ketika delivery tidak sesuai kontrak."]
 ],
 chapters:[
  {concept:"Ad tech ecosystem menghubungkan advertiser, agency, ad platform, DSP, ad server, publisher, measurement vendor, and analytics. Google Ads, Meta Ads Manager, TikTok Ads Manager, DV360, and CM360 have different setup models; Ad Ops must understand the task and system-of-record rather than assuming all dashboards use identical object hierarchies.",example:"SIMULASI — campaign plan includes Google Search, Meta, TikTok, and publisher display. Each has unique account/asset permissions and tracking, but a shared launch checklist is required.",actions:["Map who owns account, campaign, ad asset, tag, billing, and approval on each platform.","Separate buying platforms from ad servers/measurement systems.","Define system-of-record and cross-platform handoff."],practice:"Buat ad-tech map untuk campaign multi-platform: account owner, campaign object, ad object, creative, tag, platform report, billing, and escalation path.",qaFocus:["membedakan buying platform, ad server, analytics, dan verification","mengidentifikasi ownership dan permissions","menentukan source of truth per artefak"],terms:[["Ad server","Sistem untuk mengatur/menayangkan iklan dan mengukur delivery."],["Ad platform","Platform untuk membuat dan mengelola campaign iklan."],["System of record","Sistem resmi tempat data/status tertentu dipertahankan."]]},
  {concept:"Brief teknis mengubah approved strategy dan media plan menjadi field setup yang konsisten. Trafficking sheet mencakup client/brand, platform/account, campaign/ad set/ad/placement, audience, budget, flight, creative version, destination URL, UTM/macro, tag, owner, approval, and status. Naming taxonomy mempercepat search, troubleshooting, and reporting.",example:"SIMULASI — campaign TikTok launch uses old landing URL and wrong currency in campaign name. Without a standard sheet and naming review, reporting and approvals become unreliable.",actions:["Parse brief and IO into structured required fields.","Define naming syntax for brand, market, objective, product, audience, and period.","Create field validation and change-control process."],practice:"Buat trafficking sheet dan naming taxonomy untuk Meta, TikTok, Google Ads, and CM360. Sertakan field wajib, owner, status, change log, and approval.",qaFocus:["memastikan semua field brief terwakili","membuat naming yang konsisten lintas platform","merekam perubahan dan approval"],terms:[["Trafficking sheet","Workbook setup dan tracking campaign."],["Naming taxonomy","Aturan penamaan terstruktur."],["Change control","Proses approval dan dokumentasi perubahan."]]},
  {concept:"Creative specs differ by platform, placement, and format. Check dimensions/aspect ratio, file size, format, duration, codec, text/safe zones, click URL, SSL, tracking, audio/caption, and fallback. A technically accepted asset may still violate ad policy or create poor user experience; combine technical and policy QA.",example:"SIMULASI — vertical video asset is uploaded to a square placement; CTA safe zone is obscured and destination URL has broken redirect. Campaign should not go live until corrected.",actions:["Build spec matrix per platform/placement from official docs.","Validate file/format/length/ratio/text/safe zone/URL/SSL/fallback.","Check policy/rights/disclosure and approval before trafficking."],practice:"Buat creative specification matrix for Meta Feed/Stories/Reels, TikTok In-Feed, Google Display/Video, and CM360 display/video. Include QA status and fallback.",qaFocus:["menggunakan current official spec, not remembered values","memisahkan technical approval dari policy/rights approval","menguji rendering dan URL di device yang relevan"],terms:[["Aspect ratio","Perbandingan lebar dan tinggi aset."],["Safe zone","Area aman agar elemen penting tidak tertutup UI."],["Fallback asset","Aset pengganti jika format utama tidak tersedia."]]},
  {concept:"Tags, pixels, UTM, click trackers, impression trackers, and conversion events are not interchangeable. Google tag/GTM manages tags and triggers; Meta Pixel/CAPI and TikTok Pixel/Events API send platform signals; CM360 tags and Floodlight support ad serving/conversion workflows. Ad Ops must specify event_id/deduplication, privacy/consent, URL parameters, and source of truth.",example:"SIMULASI — the same purchase is sent through browser pixel and server event without shared event_id, resulting in duplication. UTM parameters are also stripped by a redirect, breaking campaign attribution.",actions:["Map business event to platform tag/event and required parameters.","Define click/impression trackers, UTM naming, macro, event_id, deduplication, and consent.","Test redirects, tag firing, parameters, and reporting before launch."],practice:"Buat tag map and parameter specification for a cross-platform campaign: Google tag/GTM, Meta Pixel+CAPI, TikTok Pixel+Events API, UTM, CM360/Floodlight, consent, event_id, and QA.",qaFocus:["membedakan UTM, pixel, server event, and ad-server tracker","menguji duplicate/missing event","menentukan privacy/consent behavior and event owner"],terms:[["Pixel","Browser-side tracking code/event collector."],["CAPI/Events API","Server-side transmission of conversion/event signals."],["Event deduplication","Penyatuan browser/server event yang merujuk kejadian sama."]]},
  {concept:"CM360 setup menghubungkan advertiser, campaign, site, placement, ad, creative, tag, and Floodlight activity. Placement adalah slot inventory/booking; ad and creative assignment controls what serves; Floodlight records activity using configured counting methods and conversion windows. CM360 is not the same as Meta/TikTok campaign structure, so map interoperability explicitly.",example:"SIMULASI — a campaign has three placements but the creative is assigned to only two; Floodlight activity uses the wrong counting method. Delivery and conversion reporting diverge despite an apparently correct campaign shell.",actions:["Build CM360 hierarchy and placement/spec map from approved plan.","Configure ads, creatives, tags, and Floodlight activities.","Validate publisher tag handoff, click/impression tracking, counting, and windows."],practice:"Buat CM360 setup walkthrough (draft/mockup) dengan advertiser, campaign, site, placement, ad, creative, placement tag, Floodlight activity, and QA record. Never claim a live production implementation without account proof.",qaFocus:["memetakan object relationships in CM360","menentukan Floodlight activity and counting method","memastikan publisher receives the correct placement tag"],terms:[["Placement","Slot inventory dalam CM360."],["Floodlight activity","Conversion/action event yang dikonfigurasi."],["Placement tag","Tag yang digunakan publisher untuk mengirim/menayangkan ad."]]},
  {concept:"Pre-launch QA is a formal release gate. Validate asset rendering, URL redirects, UTM/macro, pixel/events, targeting, geography, date/timezone, budget, bid, consent, platform policy, naming, exclusions, approval, publisher acceptance, and monitoring setup. Each test needs expected/actual outcome, evidence, owner, severity, and sign-off.",example:"SIMULASI — Meta campaign has correct creative but wrong destination URL; TikTok event fires twice; CM360 placement tag is rejected by publisher. Go-live must be blocked until critical issues close.",actions:["Define test cases and severity levels before QA.","Run tests on expected devices/placements and verify network/tag/event evidence.","Record pass/fail, fix, retest, approvals, and explicit go-live sign-off."],practice:"Buat preflight QA record for a multi-platform campaign with at least 15 test cases, evidence link/screenshot placeholder, expected/actual, owner, severity, retest, and sign-off.",qaFocus:["memisahkan critical issue dari minor issue","membuktikan expected vs actual outcome","tidak memberikan go-live approval sebelum critical failures ditutup"],terms:[["Preflight","Pemeriksaan sebelum campaign live."],["Severity","Tingkat dampak issue."],["Go-live sign-off","Persetujuan tertulis bahwa campaign siap tayang."]]},
  {concept:"Live monitoring checks delivery, spend/pacing, impressions/clicks/conversions, rejection, frequency, tag firing, URL, creative rendering, and budget. Troubleshooting should isolate whether the issue sits in account/access, inventory, audience, bid/budget, creative, policy, tag, website, or reporting latency. Change logs protect the team against repeated or conflicting edits.",example:"SIMULASI — TikTok delivery stops after a creative rejection; Google underpacing is caused by low search demand; CM360 reports impressions but the click tracker fails. Each issue requires different owner and fix.",actions:["Set daily/weekly monitoring cadence and anomaly thresholds.","Diagnose the layer before changing campaign settings.","Log incident, root cause, action, owner, evidence, and rollback if needed."],practice:"Buat monitoring dashboard/log dan troubleshoot dua kasus sintetis: underdelivery and tracking failure. Record symptoms, diagnosis tree, action, QA, and resolution.",qaFocus:["membedakan issue delivery dengan issue measurement","menggunakan escalation matrix yang tepat","merekam changes and rollback evidence"],terms:[["Underdelivery","Delivery di bawah target/commitment."],["Pacing","Kecepatan spend/delivery terhadap plan."],["Incident log","Catatan kejadian, diagnosis, tindakan, dan resolution."]]},
  {concept:"Platform discrepancy may result from event definition, attribution model/window, timezone, click vs view, data latency, deduplication, consent, invalid traffic, or currency. Reconcile only after definitions and denominators align. Document tolerance policy by measurement relationship; never invent a universal percentage tolerance for all platforms/contracts.",example:"SIMULASI — Meta reports 120 purchases, GA4 reports 95 sessions with purchase, and backend records 104 paid orders. Investigate windows, event dedup, timezone, payment status, and refunds before declaring a tracking fault.",actions:["List all reporting systems and their conversion definitions/windows.","Compare event counts, timezone, deduplication, latency, consent, and backend status.","Classify variance as expected methodological difference, data issue, or contract discrepancy."],practice:"Buat discrepancy analysis for three systems using synthetic data, with event definition table, source, window, variance, likely causes, additional evidence, and final status.",qaFocus:["menentukan apakah angka dapat dibandingkan","menginvestigasi akar discrepancy sebelum eskalasi","menyimpan evidence dan root-cause decision"],terms:[["Attribution window","Periode untuk mengkreditkan conversion ke touchpoint."],["Data latency","Jeda antara event terjadi dan report tersedia."],["Deduplication","Pencegahan event ganda."]]},
  {concept:"Billing and process control menghubungkan booking/IO, rate, period, billable metric, delivered volume, currency, tax, discount, bonus, makegood, and proof of performance. Documentation harus menjaga campaign version, approvals, access, tag changes, incidents, and archive. Ad Ops sering menjadi penjaga audit trail, tetapi Finance/Buying own final commercial approval.",example:"SIMULASI — IO memesan 1 juta impressions, CM360 proof menunjukkan 850 ribu billable. Hitung shortfall menurut kontrak dan pastikan bonus/makegood tidak dihitung sebagai paid delivery tanpa dasar.",actions:["Match IO/booking with delivery logs and billable definitions.","Reconcile rate, period, tax, currency, volume, discount, and makegood.","Archive approvals, version, troubleshooting, and evidence."],practice:"Buat billing reconciliation sheet untuk satu placement sintetis dan process-control checklist: booking, proof, invoice, variance, owner, change log, archive, and audit evidence.",qaFocus:["mencocokkan invoice dan proof pada basis kontrak","membedakan billable units dengan bonus/makegood","menyimpan dokumentasi lengkap untuk audit"],terms:[["Billable basis","Dasar volume/unit yang ditagihkan."],["Makegood","Kompensasi atas delivery kurang."],["Version control","Pengelolaan revisi artefak dengan jejak perubahan."]]},
  {concept:"Capstone Ad Ops memperlihatkan operasi teknis lintas platform dari intake sampai reconciliation. Pack harus konsisten antara approved plan, trafficking, creative specs, tags, QA, go-live, monitoring, discrepancy, and billing. Simulasi tidak boleh menyatakan bahwa placement/tag/campaign benar-benar live di platform production.",example:"SIMULASI — satu integrated campaign memuat Google Search, Meta, TikTok, dan publisher display via CM360. Tiap platform punya setup berbeda, tetapi handoff dan QA record disatukan dalam satu control pack.",actions:["Translate brief into master trafficking and platform-specific checklists.","Prepare creative/tag/measurement and perform preflight QA.","Monitor, reconcile, and present operational review with evidence."],practice:"Buat capstone operational pack: master brief, trafficking sheet, creative spec matrix, Google/Meta/TikTok/CM360 setup notes, tag map, QA record, go-live form, monitoring log, discrepancy analysis, and billing reconciliation.",qaFocus:["mengintegrasikan platform-specific workflows tanpa menganggap struktur sama","menunjukkan prelaunch and postlaunch control","membedakan simulated setup dengan production implementation"],terms:[["Operational control pack","Kumpulan dokumen untuk memastikan campaign dijalankan dan diaudit."],["Platform-specific checklist","QA berdasarkan aturan dan struktur suatu platform."],["Operational review","Evaluasi kualitas pelaksanaan dan perbaikan proses."]]}
 ]
};
